    generate_integers(8, 2) => [2, 4, 6, 8]
    generate_integers(10, 14) => []
    """
    def is_even(n):
        return n % 2 == 0

    def get_digits(n):
        return [int(d) for d in str(n)]

    def filter_even_digits(a, b):
        digits_a = get_digits(a)
        digits_b = get_digits(b)
        even_digits = []
        for d in digits_a + digits_b:
            if is_even(d):
                even_digits.append(d)
        return sorted(set(even_digits))

    return filter_even_digits(min(a, b), max(a, b))
